// The TS mirror must agree with deadroll_rules::arena and the footprints on every fixture case
// (generated by crates/rules/tests/arena_ts_fixtures.rs).
import { describe, expect, it } from "vitest";
import fixture from "./__fixtures__/arena.json";
import { covers, cellsOf, footprint, lineEnds, nearest, squareDistance } from "./footprint";
import { ARENA, delay, effectiveInitiative, nextUnit, turnDelay, upcoming } from "./timeline";

describe("timeline mirror (fixture from crates/rules)", () => {
  it("has the program's arena numbers", () => {
    expect(ARENA).toEqual(fixture.arena);
  });

  it("takes the delay under a Slow like turn_delay", () => {
    for (const c of fixture.delays) {
      expect(effectiveInitiative(c.initiative, c.slowBp), JSON.stringify(c)).toBe(c.effective);
      expect(turnDelay(c.initiative, c.slowBp), JSON.stringify(c)).toBe(c.delay);
    }
    expect(delay(0)).toBe(Math.floor(ARENA.timeScale / ARENA.initiativeBase));
  });

  it("picks the next unit and forecasts the turns like next_unit and upcoming", () => {
    for (const c of fixture.timelines) {
      expect(nextUnit(c.units), JSON.stringify(c)).toBe(c.next);
      expect(upcoming(c.units, c.delays, 8), JSON.stringify(c)).toEqual(c.upcoming);
    }
  });
});

describe("footprint mirror (fixture from crates/mapcheck)", () => {
  it("measures, covers and ends lines like the Rust footprint", () => {
    for (const c of fixture.squares) {
      expect(squareDistance(c.a, c.b), JSON.stringify(c)).toBe(c.distance);
      expect(covers(c.a, c.probe), JSON.stringify(c)).toBe(c.covers);
      expect(nearest(c.a, c.probe), JSON.stringify(c)).toEqual(c.nearest);
      expect(lineEnds(c.a, c.b), JSON.stringify(c)).toEqual({ from: c.lineFrom, through: c.lineThrough });
    }
  });

  it("lists a 2x2 square row by row", () => {
    expect(cellsOf(footprint({ x: 3, y: 4 }, 2))).toEqual([
      { x: 3, y: 4 },
      { x: 4, y: 4 },
      { x: 3, y: 5 },
      { x: 4, y: 5 },
    ]);
    expect(cellsOf(footprint({ x: 1, y: 1 }, 0))).toEqual([{ x: 1, y: 1 }]);
  });
});
